it.effect("binds only the matching PM-owned profile without moving native account files", () =>
  Effect.gen(function* () {
    const fs = yield* FileSystem.FileSystem;
    const path = yield* Path.Path;
    const root = yield* fs.makeTempDirectoryScoped({ prefix: "pm-antigravity-profile-port-" });
    const instanceId = ProviderInstanceId.make("existing-pm-account");
    const directories = { profile: path.join(root, "old-private-profile"), runtimeTemp: path.join(root, "old-private-profile", "antigravity-acp", "tmp") };
    yield* fs.makeDirectory(directories.profile);
    yield* fs.writeFileString(path.join(directories.profile, "owned-history-marker"), "unchanged");
    const [own, other] = yield* Effect.all([
      resolveAntigravityInstanceDirectories(root, instanceId),
      resolveAntigravityInstanceDirectories(root, ProviderInstanceId.make("other-account")),
    ]).pipe(Effect.provideService(AntigravityProfileDirectories, { instanceId, directories }));
    expect(own).toEqual(directories);
    expect(other.profile).not.toBe(directories.profile);
    expect(yield* fs.readFileString(path.join(directories.profile, "owned-history-marker"))).toBe("unchanged");
  }).pipe(Effect.provide(NodeServices.layer), Effect.scoped),
);
